# Helper function to check for weak algorithms in any node
weak_algorithm(node) {
    # Check String nodes for algorithm names
    node.ir_type == "String"
    algorithm := node.value
    weak_algorithm_name(algorithm)
} else {
    # Check FunctionCall nodes
    node.ir_type == "FunctionCall"
    # Check function name (e.g., filter|hash)
    function_name := node.name
    weak_algorithm_name(function_name)
    # Check arguments (e.g., 'sha1')
    some arg in node.args
    weak_algorithm(arg)
} else {
    # Check Access nodes (e.g., restore_service.user | hash('sha1'))
    node.ir_type == "Access"
    # Check the right side (attribute name)
    weak_algorithm(node.right)
} else {
    # Check Hash nodes (e.g., key-value pairs in Chef attributes)
    node.ir_type == "Hash"
    some pair in node.value
    # pair is a dict with "key" and "value"
    key := pair.key
    value := pair.value
    weak_algorithm(key)
    weak_algorithm(value)
} else {
    # Check Array nodes (e.g., cipher suites list)
    node.ir_type == "Array"
    some item in node.value
    weak_algorithm(item)
}

# Helper function to check if a string indicates a weak algorithm name
weak_algorithm_name(str) {
    # Convert to lowercase for case-insensitive matching
    lower_str := lower(str)

    # Weak symmetric ciphers
    regex.match(".*(des|3des|triple.des|desede|rc2|rc4|arc4|arcfour|blowfish|idea).*", lower_str)
} else {
    # Weak hashing algorithms
    regex.match(".*(md2|md4|md5|sha1).*", lower_str)
} else {
    # Weak encoding (mistaken for encryption)
    regex.match(".*(xor|base64|rot13|rot25|url.encod).*", lower_str)
} else {
    # Weak block modes
    regex.match(".*ecb.*", lower_str)
} else {
    # Weak protocols
    regex.match(".*(ssl[v]?[23]|tls[ _]?1[._]?[01]|ssh[ _]?1).*", lower_str)
} else {
    # Weak key sizes
    regex.match(".*(rsa[ _]?1024|des[ _]?56|3des[ _]?112|3des[ _]?168).*", lower_str)
}

